import json

def prepare_bedrock_request_body(text: str, model_id: str) -> str:
    """
    Prepares the request body for AWS Bedrock InvokeModel for text embedding.
    """
    if "titan-embed-text" in model_id:
        return json.dumps({
            "inputText": text
        })
    # Add more model-specific body preparations here if needed
    else:
        raise ValueError(f"Unsupported model ID for request body preparation: {model_id}")

def parse_bedrock_response_body(response_body_bytes: bytes, model_id: str) -> list[float]:
    """
    Parses the response body from AWS Bedrock InvokeModel for text embedding.
    """
    response_body = json.loads(response_body_bytes.decode('utf-8'))
    if "titan-embed-text" in model_id:
        return response_body.get('embedding')
    # Add more model-specific response parsing here if needed
    else:
        raise ValueError(f"Unsupported model ID for response body parsing: {model_id}")

import boto3
import json

def check_corpus_safety(text: str) -> dict:
    """
    Checks the safety of corpus text before embedding using AWS Comprehend.
    """
    comprehend = boto3.client(
        service_name='comprehend',
        region_name='us-east-1' # Example region, can be configured
    )

    # Using detect_sentiment as a proxy for safety check, as Comprehend does not have a direct "safety" API.
    # For real content moderation, other services or custom models might be needed.
    # AWS Moderation for images/videos is Rekognition. For text, it's usually custom solutions or combining various NLP outputs.
    # If the user expects a dedicated safety check, this might need adjustment to a different provider like Google Cloud's Perspective API or a custom model.
    # For this task, let's assume sentiment analysis can give some indication of harmful content (e.g., very negative sentiment).
    try:
        response = comprehend.detect_sentiment(
            Text=text,
            LanguageCode='en'
        )
        return {
            "sentiment": response.get('Sentiment'),
            "sentiment_scores": response.get('SentimentScore')
        }
    except Exception as e:
        return {"error": str(e)}
